  // Paginate
  const page = parseInt(req.query.page as string) || 0;
  const pageSize = 20;
  const slice = files.slice(page * pageSize, (page + 1) * pageSize);

  const contents = await Promise.all(
    slice.map(f => readFile(`logs/${f}`, "utf8"))
  );
  res.json(contents);
});
```

For truly large responses, use `res.write()` with streaming reads instead of buffering everything into a single `res.json()` call.

