async function getData(key: string): Promise<any> {
  if (cache.has(key)) return cache.get(key)!;
  const promise = fetchFromDB(key);
  cache.set(key, promise);
  try {
    return await promise;
  } catch (err) {
    cache.delete(key); // don't cache failures
    throw err;
  }
}
```

