    const [user, orders, balance] = await Promise.all([
      axios.get(`${SERVICES.users}/users/${req.params.userId}`, axiosConfig),
      axios.get(`${SERVICES.orders}/orders?user=${req.params.userId}`, axiosConfig),
      axios.get(`${SERVICES.payments}/balance/${req.params.userId}`, axiosConfig),
