/**
 * Transforms an array of items into a record keyed by each item's `id` property.
 * Items without an `id` are assigned a random key (non-deterministic).
 *
 * @param input - Array of items, ideally each having a unique `id` property.
 * @returns A record mapping item IDs (or random keys) to items.
 */
export function transformData(input: unknown[]): Record<string, unknown> {
  const result: Record<string, unknown> = {};
  for (const item of input) {
    // Fall back to a random key if the item has no `id`.
    // This ensures every item is represented, but keys are not stable across calls.
    const key = (item as any).id || String(Math.random());
    result[key] = item;
  }
  return result;
}
