/**
 * Buffers items for batch processing. Call `process()` to enqueue items,
 * then `flush()` to retrieve and clear the buffer.
 */
export class DataProcessor {
  private buffer: unknown[] = [];

  /** Appends an item to the internal buffer. */
  process(item: unknown): void {
    this.buffer.push(item);
  }

  /** Returns all buffered items and resets the buffer to empty. */
  flush(): unknown[] {
    const r = [...this.buffer];
    this.buffer = [];
    return r;
  }
}
