async function enrichUserData(userIds: string[]): Promise<User[]> {
  const users: User[] = [];
  for (const id of userIds) {
    try {
      const [userRes, profileRes, permRes] = await Promise.all([
        fetch(`/api/users/${id}`),
        fetch(`/api/profiles/${id}`),
        fetch(`/api/permissions/${id}`),
      ]);

      if (!userRes.ok || !profileRes.ok || !permRes.ok) {
        // fail-fast or collect partial results — choose a strategy
        throw new Error(`One or more requests failed for user ${id}`);
      }

      const [user, profile, permissions] = await Promise.all([
        userRes.json(), profileRes.json(), permRes.json(),
      ]);
      users.push({ ...user, ...profile, permissions });
    } catch (err) {
      // Propagate, skip, or collect — but make it a deliberate choice
      throw err;
    }
  }
  return users;
}
