### A11Y-001: Non-interactive elements used for interactive controls — missing roles and keyboard operability

**Severity:** Critical
**WCAG:** 4.1.2 Name, Role, Value (Level A) & 2.1.1 Keyboard (Level A)
**Evidence:** Lines 8–13 — the dropdown toggle is a `<div>` with only an `onClick` handler. Lines 20–28 — each dropdown item is also a `<div>` with only an `onClick` handler. Neither element has a `role`, `tabIndex`, or any keyboard event handler.

**Impact:** The entire component is completely inoperable for keyboard-only users and invisible to screen readers as an interactive control. A `<div>` with `onClick` is not focusable and does not respond to Enter/Space keypresses. Assistive technology will not announce this as a button or listbox.

**Recommendation:** Use a `<button>` for the toggle (which provides native keyboard support and role), and use proper ARIA listbox/combobox patterns for the menu:

```tsx
export function CustomDropdown({ options, onSelect }: DropdownProps) {
  const [isOpen, setIsOpen] = useState(false);
  const [selected, setSelected] = useState(options[0]);
  const [activeIndex, setActiveIndex] = useState(0);
  const listRef = useRef<HTMLUListElement>(null);
  const toggleId = useId();
  const listboxId = useId();

  const handleKeyDown = (e: React.KeyboardEvent) => {
    switch (e.key) {
      case 'ArrowDown':
        e.preventDefault();
        setActiveIndex((prev) => Math.min(prev + 1, options.length - 1));
        break;
      case 'ArrowUp':
        e.preventDefault();
        setActiveIndex((prev) => Math.max(prev - 1, 0));
        break;
      case 'Enter':
      case ' ':
        e.preventDefault();
        if (isOpen) {
          setSelected(options[activeIndex]);
          onSelect(options[activeIndex].value);
          setIsOpen(false);
        } else {
          setIsOpen(true);
        }
        break;
      case 'Escape':
        setIsOpen(false);
        break;
    }
  };

  return (
    <div className="dropdown" onKeyDown={handleKeyDown}>
      <button
        id={toggleId}
        className="dropdown-toggle"
        aria-haspopup="listbox"
        aria-expanded={isOpen}
        aria-controls={listboxId}
        onClick={() => setIsOpen(!isOpen)}
      >
        {selected.label}
        <span className="arrow" aria-hidden="true">{isOpen ? '▲' : '▼'}</span>
      </button>
      {isOpen && (
        <ul
          id={listboxId}
          ref={listRef}
          role="listbox"
          aria-labelledby={toggleId}
          tabIndex={-1}
        >
          {options.map((opt, index) => (
            <li
              key={opt.value}
              role="option"
              aria-selected={opt.value === selected.value}
              className={`dropdown-item ${index === activeIndex ? 'active' : ''}`}
              onClick={() => {
                setSelected(opt);
                onSelect(opt.value);
                setIsOpen(false);
              }}
            >
              {opt.label}
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}
```

