### A11Y-004: No Focus Trap — Tab Key Escapes Modal Into Background Content

**Severity:** Critical
**WCAG:** 2.4.3 Focus Order (Level A), 2.1.2 No Keyboard Trap (Level A — inverse: the trap must exist for modals per the dialog pattern)
**Location:** Entire component — no focus management logic present

**Evidence:** The component renders a full-viewport overlay (lines 8–15) that visually obscures background content, yet there is no focus trapping mechanism. A keyboard user pressing Tab will cycle focus to elements behind the overlay, which are visually hidden but still in the DOM. This violates the WAI-ARIA Dialog (Modal) pattern, which requires focus to be constrained within the dialog while it is open.

**Recommendation:**

```tsx
import { useEffect, useRef } from "react";

export function Modal({ isOpen, children }: ModalProps) {
  const modalRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (!isOpen || !modalRef.current) return;
    const focusableEls = modalRef.current.querySelectorAll<HTMLElement>(
      'button, [href], input, select, textarea, [tabindex]:not([tabindex="-1"])'
    );
    const firstEl = focusableEls[0];
    const lastEl = focusableEls[focusableEls.length - 1];
    firstEl?.focus();

    function trapFocus(e: KeyboardEvent) {
      if (e.key === "Tab") {
        if (e.shiftKey && document.activeElement === firstEl) {
          e.preventDefault();
          lastEl?.focus();
        } else if (!e.shiftKey && document.activeElement === lastEl) {
          e.preventDefault();
          firstEl?.focus();
        }
      }
    }
    document.addEventListener("keydown", trapFocus);
    return () => document.removeEventListener("keydown", trapFocus);
  }, [isOpen]);

  // ...render with ref={modalRef} on the dialog container
}
```

